const canvas=document.querySelector('#game');
const renderer=new THREE.WebGLRenderer({canvas,antialias:true,alpha:false});
renderer.setPixelRatio(Math.min(devicePixelRatio,1.65));renderer.setSize(innerWidth,innerHeight);renderer.shadowMap.enabled=true;renderer.shadowMap.type=THREE.PCFSoftShadowMap;renderer.outputColorSpace=THREE.SRGBColorSpace;renderer.toneMapping=THREE.ACESFilmicToneMapping;renderer.toneMappingExposure=1.15;
const scene=new THREE.Scene();scene.background=new THREE.Color('#102927');scene.fog=new THREE.FogExp2('#102927',.014);
const camera=new THREE.PerspectiveCamera(42,innerWidth/innerHeight,.1,120);camera.position.set(17,25,27);
scene.add(new THREE.HemisphereLight(0xbde9dd,0x263328,2.1));
const sun=new THREE.DirectionalLight(0xffe6be,3.2);sun.position.set(-12,23,10);sun.castShadow=true;sun.shadow.mapSize.set(1024,1024);sun.shadow.camera.left=-25;sun.shadow.camera.right=25;sun.shadow.camera.top=25;sun.shadow.camera.bottom=-25;scene.add(sun);
const mat=(color,rough=.8,metal=0)=>new THREE.MeshStandardMaterial({color,roughness:rough,metalness:metal});
const mats={grass:mat('#315c48'),path:mat('#8c8062'),pathEdge:mat('#5b5945'),water:mat('#287a78',.32,.16),stone:mat('#596657'),gold:mat('#e6ba69',.3,.65),blue:mat('#42c7d7',.3,.3),blueDark:mat('#1d6675'),red:mat('#e85f61',.34,.25),redDark:mat('#7e3438'),leaf:mat('#315d43'),leaf2:mat('#46724c'),wood:mat('#554433'),glow:mat('#80fff1',.2,.15),white:mat('#ecf2d5')};
const ground=new THREE.Mesh(new THREE.PlaneGeometry(42,42),mats.grass);ground.rotation.x=-Math.PI/2;ground.position.y=-.22;ground.receiveShadow=true;scene.add(ground);
// Floating arena edge and scattered terrain
const island=new THREE.Mesh(new THREE.CylinderGeometry(21.3,21.8,1,8),mat('#253a37'));island.position.y=-.75;island.receiveShadow=true;scene.add(island);
const waterDisc=new THREE.Mesh(new THREE.CircleGeometry(24,64),mat('#183b42',.35,.2));waterDisc.rotation.x=-Math.PI/2;waterDisc.position.y=-1.31;scene.add(waterDisc);
const pathGroup=new THREE.Group();scene.add(pathGroup);
function pathSegment(x,z,len,w,material,y=.015){const m=new THREE.Mesh(new THREE.BoxGeometry(len,.18,w),material);m.position.set(x,y,z);m.rotation.y=-Math.PI/4;m.receiveShadow=true;m.castShadow=true;pathGroup.add(m);return m}
pathSegment(0,0,35,6,mats.pathEdge,-.07);pathSegment(0,0,34,4.7,mats.path,.02);
// Crossing stream and a stone lane bridge
const river=new THREE.Mesh(new THREE.BoxGeometry(38,.06,2.45),mats.water);river.position.set(0,-.08,0);river.rotation.y=Math.PI/4;scene.add(river);
const bridge=new THREE.Mesh(new THREE.BoxGeometry(6.7,.3,5.25),mat('#887b60'));bridge.position.set(0,.1,0);bridge.rotation.y=-Math.PI/4;bridge.castShadow=true;bridge.receiveShadow=true;scene.add(bridge);
for(let i=-1;i<=1;i++){const rune=new THREE.Mesh(new THREE.BoxGeometry(.24,.025,.24),mats.gold);rune.position.set(i*1.35,.27,0);rune.rotation.y=Math.PI/4;scene.add(rune)}
// Scenic jungle, stones, and glowing map details
function rock(x,z,s=1){const r=new THREE.Mesh(new THREE.DodecahedronGeometry(s,0),mats.stone);r.position.set(x,s*.48-.05,z);r.scale.set(1,.75,.9);r.rotation.set(Math.random()*.2,Math.random()*3,Math.random()*.2);r.castShadow=true;r.receiveShadow=true;scene.add(r)}
function tree(x,z,s=1){const g=new THREE.Group();const trunk=new THREE.Mesh(new THREE.CylinderGeometry(.13*s,.24*s,1.45*s,7),mats.wood);trunk.position.y=.6*s;trunk.castShadow=true;g.add(trunk);for(let i=0;i<3;i++){const crown=new THREE.Mesh(new THREE.IcosahedronGeometry(.78*s-i*.08,1),i===1?mats.leaf2:mats.leaf);crown.position.set(0,(1.25+i*.42)*s,0);crown.scale.set(1,.9,1);crown.castShadow=true;g.add(crown)}g.position.set(x,0,z);scene.add(g)}
for(const [x,z,s] of [[-13,-3,1.15],[-14,-7,.9],[-11,1,.85],[-8,4,1],[-5,9,1.05],[-1,12,.9],[3,12,1.2],[11,8,1.1],[13,3,.95],[14,0,1.15],[9,-4,1.1],[5,-10,.9],[0,-13,1.15],[-6,-12,.85],[11,-8,.9],[-12,8,.95]])tree(x,z,s);
for(const [x,z,s] of [[-10,-2,.7],[-12,2,.9],[-7,6,.65],[-3,9,.6],[3,11,.75],[8,9,.6],[12,4,.85],[10,-5,.7],[5,-9,.6],[-4,-11,.7]])rock(x,z,s);
function crystal(x,z,c){const crystal=new THREE.Mesh(new THREE.OctahedronGeometry(.36,0),new THREE.MeshStandardMaterial({color:c,emissive:c,emissiveIntensity:1.2,roughness:.2}));crystal.position.set(x,.55,z);crystal.rotation.y=.4;scene.add(crystal);const light=new THREE.PointLight(c,1.2,4);light.position.copy(crystal.position);scene.add(light)}
crystal(-3,4,'#67e2c6');crystal(4,-3,'#e1bd6a');
// Circular bases
function platform(x,z,color){const p=new THREE.Mesh(new THREE.CylinderGeometry(3.2,3.35,.45,8),mat('#48564b'));p.position.set(x,.04,z);p.castShadow=true;p.receiveShadow=true;scene.add(p);const ring=new THREE.Mesh(new THREE.TorusGeometry(2.85,.075,8,48),new THREE.MeshStandardMaterial({color,emissive:color,emissiveIntensity:.42,metalness:.4}));ring.rotation.x=Math.PI/2;ring.position.set(x,.29,z);scene.add(ring)}
platform(-12,-12,0x57d8e6);platform(12,12,0xf16a6b);
// Model helpers
function sphere(radius,material,x,y,z,seg=16){const o=new THREE.Mesh(new THREE.SphereGeometry(radius,seg,12),material);o.position.set(x,y,z);o.castShadow=true;return o}
function cylinder(rt,rb,h,material,x,y,z,segments=12){const o=new THREE.Mesh(new THREE.CylinderGeometry(rt,rb,h,segments),material);o.position.set(x,y,z);o.castShadow=true;o.receiveShadow=true;return o}
function makeHero(){const g=new THREE.Group();const torso=cylinder(.58,.73,1.15,mats.blueDark,0,1.2,0,8);torso.scale.z=.72;g.add(torso);const chest=sphere(.58,mats.blue,0,1.52,0,12);chest.scale.set(1,.82,.72);g.add(chest);const head=sphere(.38,mat('#d7aa82'),0,2.12,0,12);g.add(head);const hood=sphere(.43,mats.blueDark,0,2.32,-.06,12);hood.scale.set(1,.55,.92);g.add(hood);const crest=new THREE.Mesh(new THREE.ConeGeometry(.15,.55,5),mats.gold);crest.position.set(0,2.7,.04);crest.rotation.x=.25;g.add(crest);for(const side of [-1,1]){g.add(cylinder(.23,.27,.68,mats.gold,side*.67,1.25,0,8));g.add(cylinder(.19,.22,.62,mats.blueDark,side*.32,.48,0,8));const boot=new THREE.Mesh(new THREE.BoxGeometry(.38,.22,.52),mat('#c1965a'));boot.position.set(side*.32,.17,.1);g.add(boot)}const cape=new THREE.Mesh(new THREE.ConeGeometry(.62,1.25,5),mat('#214c52'));cape.position.set(0,.85,-.43);cape.rotation.x=Math.PI;g.add(cape);const sword=cylinder(.08,.11,1.45,mats.gold,.93,1.2,.18,6);sword.rotation.z=-.42;g.add(sword);const blade=new THREE.Mesh(new THREE.ConeGeometry(.105,.5,6),mats.white);blade.position.set(1.23,1.88,.18);blade.rotation.z=-.42;g.add(blade);const aura=new THREE.Mesh(new THREE.TorusGeometry(.92,.035,6,40),new THREE.MeshBasicMaterial({color:'#53e1d7',transparent:true,opacity:.35}));aura.rotation.x=Math.PI/2;aura.position.y=.05;g.add(aura);g.userData={sword,aura};g.position.set(-8,0,-8);scene.add(g);return g}
function makeMinion(team){const group=new THREE.Group();const color=team==='blue'?mats.blue:mats.red;const dark=team==='blue'?mats.blueDark:mats.redDark;group.add(cylinder(.28,.36,.72,dark,0,.47,0,7));group.add(sphere(.27,color,0,.95,0,9));const helm=new THREE.Mesh(new THREE.ConeGeometry(.3,.34,6),team==='blue'?mats.gold:mats.red);helm.position.y=1.27;group.add(helm);group.add(cylinder(.055,.075,.68,mats.gold,.38,.7,.08,6));group.position.y=0;group.userData={team,hp:team==='blue'?160:220,maxHp:team==='blue'?160:220,speed:team==='blue'?1.25:.84,attack:team==='blue'?14:19,range:1.7,attackCd:Math.random(),type:'minion',alive:true};scene.add(group);return group}
function makeTower(team,x,z){const g=new THREE.Group(),color=team==='blue'?mats.blue:mats.red, dark=team==='blue'?mats.blueDark:mats.redDark;g.add(cylinder(1.05,1.25,1.25,dark,0,.75,0,8));g.add(cylinder(.7,.95,.8,color,0,1.75,0,8));g.add(new THREE.Mesh(new ConeGeometry(.85,.85,8),mats.gold));g.children[g.children.length-1].position.y=2.55;const orb=sphere(.4,team==='blue'?new THREE.MeshStandardMaterial({color:'#9bffff',emissive:'#41d9e8',emissiveIntensity:2}):new THREE.MeshStandardMaterial({color:'#ffc0a3',emissive:'#ff3f49',emissiveIntensity:2}),0,2.95,0);g.add(orb);const ring=new THREE.Mesh(new THREE.TorusGeometry(1.45,.055,8,40),new THREE.MeshBasicMaterial({color:team==='blue'?'#45cfe1':'#ff686e',transparent:true,opacity:.8}));ring.rotation.x=Math.PI/2;ring.position.y=.17;g.add(ring);g.position.set(x,0,z);g.userData={team,hp:team==='blue'?1450:1800,maxHp:team==='blue'?1450:1800,type:'tower',alive:true,attackCd:0};scene.add(g);return g}
function makeCore(team,x,z){const g=new THREE.Group();const c=team==='blue'?'#4edce9':'#fa6670';const core=new THREE.Mesh(new THREE.IcosahedronGeometry(1.55,1),new THREE.MeshStandardMaterial({color:c,emissive:c,emissiveIntensity:.65,metalness:.35,roughness:.25}));core.position.y=1.5;core.castShadow=true;g.add(core);const base=cylinder(1.65,2.0,.62,mat('#534b3a'),0,.38,0,8);g.add(base);const halo=new THREE.Mesh(new THREE.TorusGeometry(2.15,.09,8,48),new THREE.MeshStandardMaterial({color:c,emissive:c,emissiveIntensity:1}));halo.rotation.x=Math.PI/2;halo.position.y=.18;g.add(halo);g.position.set(x,0,z);g.userData={team,hp:team==='blue'?2500:3200,maxHp:team==='blue'?2500:3200,type:'core',alive:true};scene.add(g);return g}
const hero=makeHero(), enemyTower=makeTower('red',7,7),friendlyTower=makeTower('blue',-9,-9),enemyCore=makeCore('red',12,12),friendlyCore=makeCore('blue',-12,-12);
let entities=[],projectiles=[],effects=[],kills=0,level=1,xp=0,elapsed=0,gameOn=false,paused=false,finished=false,last=performance.now(),waveTime=1,heroAttackCd=0,respawn=0,screenMove={x:0,z:0},joystickState={active:false,id:null},soundOn=false,audioCtx=null;

