const $=s=>document.querySelector(s), hpEl=$('#hpBar'),mpEl=$('#mpBar'),hpText=$('#hpText'),mpText=$('#mpText'),timerEl=$('#timer');
const player={hp:680,maxHp:680,mp:320,maxMp:320,damage:47,speed:5.1,shield:0,attackCd:0,dead:false};
function toast(msg){const t=$('#toast');t.textContent=msg;t.classList.add('show');clearTimeout(toast.t);toast.t=setTimeout(()=>t.classList.remove('show'),1900)}
function updateBars(){hpEl.style.width=`${Math.max(0,player.hp/player.maxHp*100)}%`;mpEl.style.width=`${Math.max(0,player.mp/player.maxMp*100)}%`;hpText.textContent=`${Math.ceil(player.hp)} / ${player.maxHp}`;mpText.textContent=`${Math.floor(player.mp)} / ${player.maxMp}`;$('#level').textContent=`LV. ${level}`;$('#blueScore').textContent=kills;$('#miniPlayer').style.left=`${Math.max(8,Math.min(89,(hero.position.x+20)/40*100))}%`;$('#miniPlayer').style.bottom=`${Math.max(9,Math.min(82,(hero.position.z+20)/40*100))}%`}
function distance(a,b){return Math.hypot(a.position.x-b.position.x,a.position.z-b.position.z)}
function enemiesOf(team){return entities.filter(e=>e.userData.alive&&e.userData.team!==team)}
function addEffect(position,color,scale=1){const ring=new THREE.Mesh(new THREE.TorusGeometry(.35,.07,6,24),new THREE.MeshBasicMaterial({color,transparent:true,opacity:.9}));ring.position.set(position.x,.22,position.z);ring.rotation.x=Math.PI/2;scene.add(ring);effects.push({mesh:ring,t:0,duration:.5,scale})}
function projectile(from,to,team,damage,color){const orb=new THREE.Mesh(new THREE.SphereGeometry(.16,8,8),new THREE.MeshBasicMaterial({color}));orb.position.set(from.x,from.y+1.4,from.z);scene.add(orb);projectiles.push({mesh:orb,target:to,team,damage,speed:13,color})}
function damageTarget(target,amount,team){if(!target||target.userData.alive===false)return;const d=target.userData;if(d.team===team)return;if(d.type==='core'&&d.team==='red'&&enemyTower.userData.alive){toast('Hancurkan Outpost lebih dulu!');return}d.hp-=amount;addEffect(target.position,team==='blue'?'#69f2df':'#ff7474',.6);if(d.hp<=0){d.hp=0;d.alive=false;if(d.type==='minion'){scene.remove(target);entities=entities.filter(e=>e!==target);if(team==='blue'){kills++;xp+=30;player.hp=Math.min(player.maxHp,player.hp+22);if(xp>=level*100){xp-=level*100;level++;player.damage+=5;player.maxHp+=35;player.hp+=35;player.maxMp+=14;toast(`LEVEL UP · LEVEL ${level}`)}updateBars()}else{kills=Math.max(0,kills-1);$('#redScore').textContent=Number($('#redScore').textContent)+1}}
else if(d.type==='tower'){target.visible=false;$('#objectiveTitle').textContent='CORE EXPOSED';toast('Outpost hancur! Serang core lawan!');}
else if(d.type==='core'){if(d.team==='red')finish(true);else finish(false)}else if(d.type==='hero'){target.visible=false}}
}
function targetForHero(range=4){let list=enemiesOf('blue').filter(e=>distance(hero,e)<range);if(!list.length){if(distance(hero,enemyTower)<range+1&&enemyTower.userData.alive)return enemyTower;if(!enemyTower.userData.alive&&distance(hero,enemyCore)<range+1)return enemyCore}list.sort((a,b)=>distance(hero,a)-distance(hero,b));return list[0]||null}
function attack(){if(!gameOn||paused||finished||player.dead||player.attackCd>0)return;player.attackCd=.54;const target=targetForHero(4.1);if(!target){toast('Dekati target untuk menyerang');return}hero.rotation.y=Math.atan2(target.position.x-hero.position.x,target.position.z-hero.position.z);projectile(hero.position,target,'blue',player.damage,'#a8fff4');sound(420,.065)}
function ability(id){if(!gameOn||paused||finished||player.dead)return;const cfg={q:{cost:48,cd:8},w:{cost:62,cd:7},e:{cost:115,cd:22}}[id];if(cooldowns[id]>0)return;if(player.mp<cfg.cost){toast('Energi tidak cukup');return}player.mp-=cfg.cost;cooldowns[id]=cfg.cd;const near=enemiesOf('blue').filter(e=>distance(hero,e)<(id==='e'?6:id==='w'?4.8:0));if(id==='q'){player.shield=5;player.hp=Math.min(player.maxHp,player.hp+110);hero.userData.aura.material.opacity=.95;setTimeout(()=>hero.userData.aura.material.opacity=.35,1800);addEffect(hero.position,'#74f8ed',2.2);toast('AEGIS · Perisai aktif');sound(620,.14)}
if(id==='w'){const target=targetForHero(5)||enemyTower;for(const e of near)if(distance(hero,e)<4.8)damageTarget(e,100+level*13,'blue');if(target&&target!==enemyTower&&target.userData.type==='minion'){}const wave=new THREE.Mesh(new THREE.TorusGeometry(1,.17,8,32),new THREE.MeshBasicMaterial({color:'#6ceade',transparent:true,opacity:.85}));wave.position.set(hero.position.x,.32,hero.position.z);wave.rotation.x=Math.PI/2;scene.add(wave);effects.push({mesh:wave,t:0,duration:.75,scale:5});toast('RIFT WAVE · Gelombang dilepas');sound(280,.17)}
if(id==='e'){const impact=targetForHero(7)||enemyTower;const center=impact?.position||hero.position;for(const e of enemiesOf('blue'))if(distance(e,{position:center})<5.7)damageTarget(e,235+level*30,'blue');if(!enemyTower.userData.alive&&distance(enemyCore,{position:center})<5)damageTarget(enemyCore,235+level*30,'blue');const blast=new THREE.Mesh(new THREE.CircleGeometry(.7,32),new THREE.MeshBasicMaterial({color:'#ffc868',transparent:true,opacity:.68,side:THREE.DoubleSide}));blast.rotation.x=-Math.PI/2;blast.position.set(center.x,.38,center.z);scene.add(blast);effects.push({mesh:blast,t:0,duration:1,scale:7});toast('STARFALL · Hantaman bintang!');sound(180,.28)}updateBars()}
const cooldowns={q:0,w:0,e:0};
for(const [id,key] of [['q','skillQ'],['w','skillW'],['e','skillE']])$(`#${key}`).addEventListener('pointerdown',e=>{e.preventDefault();ability(id)});
$('#attackBtn').addEventListener('pointerdown',e=>{e.preventDefault();attack()});
function spawnWave(){for(let i=0;i<3;i++){for(const team of ['blue','red']){const m=makeMinion(team),off=(i-1)*1.2;m.position.set(team==='blue'?-10+off:10-off,0,team==='blue'?-10-off:10+off);entities.push(m)}}waveTime=12;toast('Pasukan tiba di lane!')}

