function updateProjectiles(dt){for(const p of [...projectiles]){if(!p.target||p.target.userData.alive===false){scene.remove(p.mesh);projectiles=projectiles.filter(x=>x!==p);continue}const dest=new THREE.Vector3(p.target.position.x,p.target.position.y+1.05,p.target.position.z),delta=dest.clone().sub(p.mesh.position),step=p.speed*dt;if(delta.length()<step+.22){if(p.target===hero){if(p.team==='red'&&!player.dead){const dmg=Math.max(0,p.damage-player.shield);player.hp-=dmg;if(player.hp<=0){player.hp=0;player.dead=true;respawn=5;hero.visible=false;toast('Kamu tumbang · kembali dalam 5 detik')}updateBars()}}else damageTarget(p.target,p.damage,p.team);scene.remove(p.mesh);projectiles=projectiles.filter(x=>x!==p)}else{p.mesh.position.addScaledVector(delta.normalize(),step);p.mesh.rotation.y+=dt*8}}}
function updateEffects(dt){for(const e of [...effects]){e.t+=dt;const progress=Math.min(1,e.t/e.duration);e.mesh.scale.setScalar(1+progress*e.scale);e.mesh.material.opacity=Math.max(0,1-progress);if(e.t>=e.duration){scene.remove(e.mesh);effects=effects.filter(x=>x!==e)}}}
function update(dt){if(!gameOn||paused||finished)return;elapsed+=dt;player.attackCd=Math.max(0,player.attackCd-dt);for(const k in cooldowns)cooldowns[k]=Math.max(0,cooldowns[k]-dt);player.mp=Math.min(player.maxMp,player.mp+5*dt);player.hp=Math.min(player.maxHp,player.hp+1.7*dt);if(player.dead){respawn-=dt;if(respawn<=0){player.dead=false;player.hp=player.maxHp*.55;hero.visible=true;hero.position.set(-8,0,-8);toast('Kembali ke arena!')}}if(!player.dead){let x=(keys.d||keys.arrowright?1:0)-(keys.a||keys.arrowleft?1:0)+screenMove.x,z=(keys.s||keys.arrowdown?1:0)-(keys.w||keys.arrowup?1:0)+screenMove.z;const len=Math.hypot(x,z);if(len>.08){x/=Math.max(1,len);z/=Math.max(1,len);hero.position.x+=x*player.speed*dt;hero.position.z+=z*player.speed*dt;hero.position.x=THREE.MathUtils.clamp(hero.position.x,-17,17);hero.position.z=THREE.MathUtils.clamp(hero.position.z,-17,17);hero.rotation.y=Math.atan2(x,z);hero.position.y=Math.sin(elapsed*9)*.035}if((attackHeld||keys[' '])&&player.attackCd<=0)attack()}waveTime-=dt;if(waveTime<=0)spawnWave();updateMinions(dt);towerFire(enemyTower,dt);towerFire(friendlyTower,dt);updateProjectiles(dt);updateEffects(dt);$('#objectiveTitle').textContent=enemyTower.userData.alive?'BREAK THE OUTPOST':'CORE EXPOSED';timerEl.textContent=`${String(Math.floor(elapsed/60)).padStart(2,'0')}:${String(Math.floor(elapsed%60)).padStart(2,'0')}`;updateBars();const focus=hero.position.clone();camera.position.lerp(new THREE.Vector3(focus.x-14,focus.y+21,focus.z-14),Math.min(1,dt*2));camera.lookAt(focus.x,focus.y+.2,focus.z)}
